'use strict';
const $=id=>document.getElementById(id),E=window.Rahasya;let key=E.dateKey(),mode='easy',c,state,person='0',storageAvailable=true,loadedRaw=null,syncConflict=false,isDailyView=true;const memory=new Map();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k){if(!storageAvailable&&memory.has(k))return memory.get(k);try{const v=localStorage.getItem(k);if(v!==null)memory.set(k,v);else memory.delete(k);return v;}catch{storageAvailable=false;return memory.get(k)??null;}}
function write(k,v){memory.set(k,v);try{localStorage.setItem(k,v);}catch{storageAvailable=false;}storageNotice();}
function storageNotice(){if($('storage-notice'))$('storage-notice').textContent=storageAvailable?'ನಿಮ್ಮ ಪ್ರಗತಿ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಉಳಿಯುತ್ತದೆ.':'ಶಾಶ್ವತವಾಗಿ ಉಳಿಸಲು ಸಾಧ್ಯವಾಗುತ್ತಿಲ್ಲ. ಈ ಪುಟ ತೆರೆದಿರುವವರೆಗೆ ಪ್ರಗತಿ ಉಳಿಯುತ್ತದೆ; ಪುಟ ಮುಚ್ಚುವ ಮೊದಲು ಗಮನಿಕೆಗಳನ್ನು ನಕಲಿಸಿಕೊಳ್ಳಿ.';}
function emptyState(){return window.RahasyaState.blank();}
function storageKey(){return 'rahasya-v1:'+key+':'+mode;}
function load(){c=E.createCase(key,mode);state=emptyState();loadedRaw=read(storageKey());try{state=window.RahasyaState.normalize(JSON.parse(loadedRaw),c);}catch{}syncConflict=false;$('sync-notice').hidden=true;person=c.suspects[0].id;render();checkDay();}
function fresh(){if(syncConflict)return false;const latest=read(storageKey());if(latest!==loadedRaw){syncConflict=true;$('sync-notice').hidden=false;return false;}return true;}
function currentScore(){return state.solved&&Number.isFinite(state.finalScore)?state.finalScore:E.score(state.highest,state.attempts);}
function save(){if(!fresh())return false;loadedRaw=JSON.stringify(state);write(storageKey(),loadedRaw);return true;}
function formatDate(k){return new Intl.DateTimeFormat('kn-IN',{timeZone:'Asia/Kolkata',year:'numeric',month:'long',day:'numeric'}).format(new Date(k+'T12:00:00+05:30'));}
function option(v,label){return `<option value="${esc(v)}">${esc(label)}</option>`;}
function render(){
$('date').textContent=formatDate(key);$('case-number').textContent='ಕಡತ / '+key.replaceAll('-','.');$('title').textContent=c.title;$('intro').textContent=c.intro;
$('status').textContent=state.solved?'ಪ್ರಕರಣ ಭೇದಿಸಲಾಗಿದೆ':'ತನಿಖೆ ನಡೆಯುತ್ತಿದೆ';$('daily').classList.toggle('active',key===E.dateKey());$('archive').classList.toggle('active',key!==E.dateKey());
$('victim').innerHTML=`<b>${esc(c.victim.name)}</b> ಅವರ ಶವ <b>${esc(c.rooms[2].name)}</b> ಸ್ಥಳದಲ್ಲಿ ${c.times[3]}ಕ್ಕೆ ಪತ್ತೆಯಾಗಿದೆ.`;
$('facts').innerHTML=[`ಆಯುಧಗಳು ${c.times[0]}ಕ್ಕೆ ಕೆಳಗಿನ ಸ್ಥಳಗಳಲ್ಲಿದ್ದವು. ಆ ಸಮಯದಿಂದ ಮಾತ್ರ ಅವುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ಸಾಧ್ಯವಿತ್ತು.`,`ಘಟನೆ ${c.times[0]}ರಿಂದ ${c.times[3]}ರ ನಡುವಿನ ನಾಲ್ಕು ಸಮಯಗಳಲ್ಲಿ ಒಂದರಲ್ಲಿ ನಡೆದಿದೆ. ಅಪರಾಧಿ ಮತ್ತು ಬಲಿಯಾದ ವ್ಯಕ್ತಿ ಮಾತ್ರ ಆ ಸ್ಥಳದಲ್ಲಿದ್ದರು.`,`ಶವವನ್ನು ಸ್ಥಳಾಂತರಿಸಿಲ್ಲ. ಅಪರಾಧಿ ಶವದ ಜೊತೆ ಸಿಕ್ಕಿಬಿದ್ದಿಲ್ಲ. ಬೇರೆ ಯಾರೂ ಕಟ್ಟಡಕ್ಕೆ ಬಂದಿಲ್ಲ.`,`ಅಪರಾಧಿ ಆಯುಧವನ್ನು ಘಟನೆಗೂ ಹಿಂದಿನ ಸಮಯದಲ್ಲಿ, ಯಾರೂ ನೋಡದಿದ್ದಾಗ ತೆಗೆದುಕೊಂಡಿದ್ದಾರೆ. ಆಯುಧವನ್ನು ಮತ್ತೊಬ್ಬರಿಗೆ ಕೊಟ್ಟಿಲ್ಲ.`].map(x=>`<li>${x}</li>`).join('');
$('suspects').innerHTML=c.suspects.map(p=>`<button type="button" class="suspect" data-suspect="${p.id}" aria-label="${esc(p.name)} ಅವರ ಕಾಲರೇಖೆ ತೆರೆಯಿರಿ"><span class="avatar" aria-hidden="true">${esc(initial(p.name))}</span><span><b>${esc(p.name)}</b><small>${esc(p.role)}</small></span><span class="suspect-open" aria-hidden="true">⌕</span></button>`).join('');
$('room-map').innerHTML=c.rooms.map((r,i)=>`${i?'<div class="connector" aria-hidden="true"></div>':''}<div class="room ${i===2?'crime':''}"><span class="room-icon" aria-hidden="true">${r.icon}</span><span>${r.name}</span>${i===2?'<small>ಘಟನಾ ಸ್ಥಳ</small>':''}</div>`).join('');
$('weapons').innerHTML=c.weapons.map(w=>`<div class="weapon-row"><span>${w.icon} ${w.name}</span><small>${c.rooms[Number(w.room)].name}</small></div>`).join('');
$('killer').innerHTML=option('','ವ್ಯಕ್ತಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡಿ')+c.suspects.map(p=>option(p.id,p.name)).join('');$('weapon').innerHTML=option('','ಆಯುಧವನ್ನು ಆಯ್ಕೆ ಮಾಡಿ')+c.weapons.map(w=>option(w.id,w.icon+' '+w.name)).join('');$('time').innerHTML=option('','ಸಮಯವನ್ನು ಆಯ್ಕೆ ಮಾಡಿ')+c.times.map(t=>option(t,t)).join('');
for(const id of ['killer','weapon','time'])$(id).value=state.answer[id];
$('notes').value=state.notes;renderClue();renderBoard();renderResult();storageNotice();
}
function renderClue(){const clue=c.clues[state.clue];$('clue-count').textContent=`${state.clue+1} / ${c.clues.length}`;$('clue-type').textContent=clue.type;$('clue-text').textContent=clue.text;$('prev-clue').disabled=state.clue===0;$('next-clue').disabled=state.clue===c.clues.length-1;$('next-clue').textContent=state.clue===c.clues.length-1?'ಎಲ್ಲ ಸುಳಿವು ಓದಿದ್ದೀರಿ':'ಮುಂದಿನ ಸುಳಿವು';$('clue-dots').innerHTML=c.clues.map((_,i)=>`<span class="dot ${i<=state.highest?'read':''} ${i===state.clue?'current':''}"></span>`).join('');$('easy').setAttribute('aria-pressed',String(mode==='easy'));$('hard').setAttribute('aria-pressed',String(mode==='hard'));$('score').textContent=currentScore();updateProgress();}
function changeClue(delta){if(!fresh())return;const next=state.clue+delta;if(next<0||next>=8)return;state.clue=next;state.highest=Math.max(next,state.highest);save();renderClue();if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)$('clue-text').animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:220});}
function renderBoard(){
$('person-tabs').innerHTML=[...c.suspects,c.victim].map(p=>`<button role="tab" id="person-${p.id}" aria-controls="timeline-panel" tabindex="${p.id===person?0:-1}" aria-selected="${p.id===person}" data-person="${p.id}">${p.name}${p.id===c.victim.id?' · ಮೃತ ವ್ಯಕ್ತಿ':''}</button>`).join('');
$('timeline').querySelector('thead').innerHTML='<tr><th scope="col">ಸ್ಥಳ / ಸಮಯ</th>'+c.times.map(t=>`<th scope="col">${t}</th>`).join('')+'</tr>';
const p=c.cast.find(x=>x.id===person);
$('timeline').querySelector('tbody').innerHTML=c.rooms.map(r=>`<tr><th scope="row">${r.icon} ${r.name}</th>${c.times.map((t,i)=>{const id=person+'-'+r.id+'-'+i,v=state.marks[id]||0;return `<td><button data-mark="${id}" class="${v===1?'mark-yes':v===2?'mark-no':''}" aria-label="${p.name}, ${r.name}, ${t}: ${v===1?'ಇದ್ದರು':v===2?'ಇರಲಿಲ್ಲ':'ತಿಳಿದಿಲ್ಲ'}">${v===1?'✓':v===2?'×':'?'}</button></td>`;}).join('')}</tr>`).join('');
$('timeline-panel').setAttribute('aria-labelledby','person-'+person);
let conflicts=0;for(let t=0;t<4;t++)if(c.rooms.filter(r=>state.marks[person+'-'+r.id+'-'+t]===1).length>1)conflicts++;$('board-warning').hidden=!conflicts;$('board-warning').textContent=conflicts?'ಒಂದೇ ಸಮಯದಲ್ಲಿ ಒಂದಕ್ಕಿಂತ ಹೆಚ್ಚು ಸ್ಥಳಗಳಿಗೆ ✓ ಗುರುತು ಇದೆ. ನಿಮ್ಮ ಊಹೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.':'';
$('mark-count').textContent=Object.values(state.marks).filter(Boolean).length+' ಗುರುತುಗಳು';
}
function renderResult(message=''){
const container=$('feedback');container.innerHTML='';if(state.solved){container.innerHTML=`<div class="feedback success"><span class="solved-seal" aria-hidden="true">✓</span><b>ಅದ್ಭುತ! ರಹಸ್ಯ ಭೇದಿಸಿದ್ದೀರಿ.</b><p>${currentScore()} / 100 ಅಂಕ · ${state.finalClues??state.highest+1} ಸುಳಿವು · ${state.attempts} ತಪ್ಪು ಪ್ರಯತ್ನ</p><button class="secondary" id="solution">ಉತ್ತರದ ವಿವರಣೆ</button></div>`;$('solution').onclick=showSolution;}else if(message){container.innerHTML=`<div class="feedback">${esc(message)}</div>`;}
for(const el of $('accuse-form').elements)el.disabled=state.solved;
$('status').textContent=state.solved?'ಪ್ರಕರಣ ಭೇದಿಸಲಾಗಿದೆ':'ತನಿಖೆ ನಡೆಯುತ್ತಿದೆ';$('score').textContent=currentScore();document.body.classList.toggle('case-solved',state.solved);updateProgress();
}
function accuse(answer){
if(state.solved)return{solved:true,score:currentScore()};if(!fresh())return{error:'ಇನ್ನೊಂದು ಟ್ಯಾಬ್‌ನ ಇತ್ತೀಚಿನ ಪ್ರಗತಿ ತೆರೆಯಿರಿ.'};
let correct;try{correct=E.checkAnswer(c,answer);}catch(e){renderResult(e.message);return{error:e.message};}
const fingerprint=[answer.killer,answer.weapon,answer.time].join('|');
if(state.rejected.includes(fingerprint)){renderResult('ಈ ತೀರ್ಮಾನವನ್ನು ಈಗಾಗಲೇ ಪರಿಶೀಲಿಸಿದ್ದೀರಿ. ಹೊಸ ಆಯ್ಕೆಯನ್ನು ಪ್ರಯತ್ನಿಸಿ. ಮತ್ತೊಮ್ಮೆ ಅಂಕ ಕಡಿತವಾಗಿಲ್ಲ.');return{solved:false,duplicate:true,score:currentScore()};}
state.answer={...answer};if(correct){state.finalScore=currentScore();state.finalClues=state.highest+1;state.solved=true;}else{state.attempts++;state.rejected.push(fingerprint);}
save();renderResult(correct?'':'ಇನ್ನೂ ಹೊಂದಿಕೆಯಾಗಿಲ್ಲ. ಕನಿಷ್ಠ ಒಂದು ಉತ್ತರ ತಪ್ಪಾಗಿದೆ. ಸುಳಿವುಗಳನ್ನು ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ.');return{solved:correct,score:currentScore()};}
function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function showSolution(){modal('ಪ್ರಕರಣದ ಪರಿಹಾರ',`<p><b>${c.cast.find(p=>p.id===c.answer.killer).name} · ${c.weapons[0].name} · ${c.answer.time}</b></p><ol>${c.explanation.map(x=>`<li>${x}</li>`).join('')}</ol><p class="caption">ನಿಮ್ಮ ಟಿಪ್ಪಣಿಗಳನ್ನು ಆಟ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಬದಲಾಯಿಸುವುದಿಲ್ಲ.</p>`);}
function showHelp(){modal('ಆಡುವುದು ಹೇಗೆ?',`<p>ಸುಳಿವುಗಳ ಸಹಾಯದಿಂದ <b>ಅಪರಾಧಿ, ಆಯುಧ ಮತ್ತು ಘಟನೆ ನಡೆದ ಸಮಯ</b> ಕಂಡುಹಿಡಿಯಿರಿ.</p><ol><li>ಪ್ರಕರಣದ ವಿವರ ಮತ್ತು ನಕ್ಷೆ ಓದಿ. ರೇಖೆಯಿಂದ ಸಂಪರ್ಕವಿರುವ ಪಕ್ಕದ ಸ್ಥಳಕ್ಕೆ ಪ್ರತಿ 15 ನಿಮಿಷಕ್ಕೆ ಒಮ್ಮೆ ಚಲಿಸಬಹುದು. ಅದೇ ಸ್ಥಳದಲ್ಲೂ ಉಳಿಯಬಹುದು.</li><li>ಸುಳಿವುಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಓದಿ. ಸರಳ ಆಟದಲ್ಲಿ ಎಲ್ಲ ಹೇಳಿಕೆಗಳೂ ನಿಜ. ಕಠಿಣ ಆಟದಲ್ಲಿ ಅಪರಾಧಿಯ ಹೇಳಿಕೆ ಸುಳ್ಳಾಗಬಹುದು; ಭದ್ರತಾ ದಾಖಲೆ ಮತ್ತು ವೈದ್ಯಕೀಯ ಸಾಕ್ಷ್ಯ ಯಾವಾಗಲೂ ನಿಜ.</li><li>ಟಿಪ್ಪಣಿ ಪಟ್ಟಿಯಲ್ಲಿ ವ್ಯಕ್ತಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡಿ. ಕೋಶವನ್ನು ಒತ್ತಿದಾಗ ? → ✓ → × → ? ಎಂದು ಗುರುತು ಬದಲಾಗುತ್ತದೆ. ಸಂಪೂರ್ಣ ಪಟ್ಟಿಯನ್ನು ತುಂಬಬೇಕಾಗಿಲ್ಲ.</li><li>ಆಯುಧವನ್ನು ಘಟನೆಯ ಹಿಂದಿನ ಸಮಯದಲ್ಲೇ ತೆಗೆದುಕೊಂಡಿರಬೇಕು. ಆಯುಧಗಳ ಆರಂಭಿಕ ಸ್ಥಳ ನಕ್ಷೆಯ ಕೆಳಗೆ ಇದೆ.</li><li>ಮೂರು ಉತ್ತರಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಿ ತೀರ್ಮಾನ ಪರಿಶೀಲಿಸಿ. ಸರಿಯಾದ ಉತ್ತರಕ್ಕೆ ಅದರ ವಿವರಣೆಯೂ ಸಿಗುತ್ತದೆ.</li></ol><h3>ಅಂಕಗಳು</h3><p>ಆರಂಭದಲ್ಲಿ 100 ಅಂಕ. ಮೊದಲ ಸುಳಿವು ಉಚಿತ; ಪ್ರತಿ ಹೊಸ ಸುಳಿವಿಗೆ 6 ಅಂಕ ಕಡಿತ. ಪ್ರತಿ ಹೊಸ ತಪ್ಪು ತೀರ್ಮಾನಕ್ಕೆ 15 ಅಂಕ ಕಡಿತ. ಅದೇ ತಪ್ಪು ಉತ್ತರವನ್ನು ಮತ್ತೆ ಸಲ್ಲಿಸಿದರೆ ಅಂಕ ಕಡಿತವಿಲ್ಲ. ಅಂಕ ಶೂನ್ಯಕ್ಕಿಂತ ಕೆಳಗೆ ಹೋಗುವುದಿಲ್ಲ.</p><h3>ದಿನದ ಪ್ರಕರಣ</h3><p>ಭಾರತೀಯ ಸಮಯದ ಪ್ರಕಾರ ಪ್ರತಿದಿನ ಪ್ರಕರಣ ಬದಲಾಗುತ್ತದೆ. ಹಿಂದಿನ ಏಳು ದಿನಗಳ ಪ್ರಕರಣಗಳನ್ನೂ ಆಡಬಹುದು. ಸರಳ ಮತ್ತು ಕಠಿಣ ಆಟದ ಪ್ರಗತಿ ಪ್ರತ್ಯೇಕವಾಗಿ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಉಳಿಯುತ್ತದೆ.</p>`);}
function showArchive(){const today=E.dateKey();modal('ಹಿಂದಿನ ಪ್ರಕರಣಗಳು',`<p>ಹಿಂದಿನ ಏಳು ದಿನಗಳ ಕಡತಗಳಲ್ಲಿ ಒಂದನ್ನು ತೆರೆಯಿರಿ.</p><div class="archive-list">${Array.from({length:7},(_,i)=>{const d=E.previousDate(today,i+1),cc=E.createCase(d);return `<button data-day="${d}"><b>${cc.title}</b><small>${formatDate(d)}</small></button>`;}).join('')}</div>`);}
function changeMode(m){if(!['easy','hard'].includes(m)||mode===m||!fresh())return;mode=m;write('rahasya-mode',mode);load();}
$('daily').onclick=()=>{isDailyView=true;key=E.dateKey();load();window.scrollTo({top:0,behavior:'smooth'});};$('archive').onclick=showArchive;$('help').onclick=showHelp;$('easy').onclick=()=>changeMode('easy');$('hard').onclick=()=>changeMode('hard');$('prev-clue').onclick=()=>changeClue(-1);$('next-clue').onclick=()=>changeClue(1);
$('person-tabs').onclick=e=>{const b=e.target.closest('[data-person]');if(b){person=b.dataset.person;renderBoard();$('person-tabs').querySelector(`[data-person="${person}"]`).focus();}};
$('timeline').onclick=e=>{const b=e.target.closest('[data-mark]');if(b&&fresh()){const id=b.dataset.mark;state.marks[id]=((state.marks[id]||0)+1)%3;save();renderBoard();$('timeline').querySelector(`[data-mark="${id}"]`).focus();}};
$('person-tabs').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=[...c.suspects,c.victim].map(p=>p.id),i=ids.indexOf(person);person=e.key==='Home'?ids[0]:e.key==='End'?ids[3]:ids[(i+(e.key==='ArrowRight'?1:3))%4];renderBoard();$('person-tabs').querySelector(`[data-person="${person}"]`).focus();};
$('notes').oninput=e=>{state.notes=e.target.value.slice(0,3000);save();};for(const id of ['killer','weapon','time'])$(id).onchange=e=>{state.answer[id]=e.target.value;save();};$('accuse-form').onsubmit=e=>{e.preventDefault();accuse({killer:$('killer').value,weapon:$('weapon').value,time:$('time').value});};
$('clear-notes').onclick=()=>modal('ಗುರುತುಗಳನ್ನು ಅಳಿಸಬೇಕೇ?',`<p>ಈ ಕಠಿಣತೆಯ ಪ್ರಕರಣದ ಎಲ್ಲಾ ವ್ಯಕ್ತಿಗಳ ಕಾಲರೇಖೆಯ ಗುರುತುಗಳು ಅಳಿಯುತ್ತವೆ. ನಿಮ್ಮ ಬರಹದ ಗಮನಿಕೆಗಳು ಉಳಿಯುತ್ತವೆ.</p><div class="dialog-actions"><button id="cancel-clear" class="secondary">ಬೇಡ</button><button id="confirm-clear" class="primary">ಗುರುತು ಅಳಿಸಿ</button></div>`);
$('modal-body').onclick=e=>{const b=e.target.closest('[data-day]');if(b&&E.validDate(b.dataset.day)){isDailyView=false;key=b.dataset.day;$('modal').close();load();window.scrollTo({top:0,behavior:'smooth'});}if(e.target.id==='confirm-clear'&&fresh()){state.marks={};save();renderBoard();$('modal').close();}if(e.target.id==='cancel-clear')$('modal').close();};
$('close-modal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}};
$('about').onclick=()=>modal('ರಹಸ್ಯದ ಬಗ್ಗೆ',`<p><b>ರಹಸ್ಯ</b> ಎಂಬುದು Mystery-o-matic ಆಟದ ತಾರ್ಕಿಕ ತನಿಖೆಯಿಂದ ಪ್ರೇರಿತವಾದ ಸ್ವತಂತ್ರ ಕನ್ನಡ ಆಟ.</p><p>ಇಲ್ಲಿನ ಕಥೆಗಳು, ಹೆಸರುಗಳು ಮತ್ತು ಸುಳಿವುಗಳು ಈ ರೂಪಾಂತರಕ್ಕಾಗಿ ರಚಿಸಲಾದ ಕಾಲ್ಪನಿಕ ವಿಷಯಗಳು. ಇದು ಮೂಲ ತಾಣದ ಅಧಿಕೃತ ಅನುವಾದವಲ್ಲ; ಅದರ ದಿನದ ಪ್ರಕರಣಗಳನ್ನು ಪಡೆಯುವುದಿಲ್ಲ.</p><p>ದಿನಾಂಕದ ಆಧಾರದಲ್ಲಿ ಸ್ಥಳಗಳು, ಪಾತ್ರಗಳು, ಸಮಯ ಮತ್ತು ಆಯುಧಗಳು ಆಯ್ಕೆಯಾಗುತ್ತವೆ. ಪ್ರಕರಣಗಳು ಒಂದೇ ತಾರ್ಕಿಕ ಮಾದರಿಯ ರೂಪಾಂತರಗಳು; ಕೆಲವು ಅಂಶಗಳು ಮರುಕಳಿಸಬಹುದು.</p><p>ಖಾತೆ ಅಥವಾ ವೈಯಕ್ತಿಕ ವಿವರಗಳ ಅಗತ್ಯವಿಲ್ಲ. ಆಟದ ಪ್ರಗತಿ ಈ ಸಾಧನದ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಉಳಿಯುತ್ತದೆ.</p><a href="https://mystery-o-matic.com/" target="_blank" rel="noopener noreferrer">ಮೂಲ ಆಟವನ್ನು ನೋಡಿ</a>`);
function initial(name){return typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('kn',{granularity:'grapheme'}).segment(name)][0].segment:name.slice(0,1);}
function updateProgress(){const n=state.highest+1;$('progress-text').textContent=state.solved?'ಪ್ರಕರಣ ಭೇದಿಸಲಾಗಿದೆ':`${n} / 8 ಸುಳಿವು ಓದಿದ್ದೀರಿ`;$('evidence-progress').value=n;$('evidence-number').textContent=String(state.clue+1).padStart(2,'0');}
function checkDay(){const newer=E.dateKey()!==key;$('day-notice').hidden=!isDailyView||!newer;}
$('open-today').onclick=()=>{isDailyView=true;key=E.dateKey();load();window.scrollTo({top:0,behavior:'smooth'});};
$('reload-progress').onclick=()=>load();
$('suspects').onclick=e=>{const b=e.target.closest('[data-suspect]');if(b){person=b.dataset.suspect;renderBoard();$('notebook').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('person-tabs').querySelector(`[data-person="${person}"]`).focus({preventScroll:true});}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkDay();fresh();}});
window.addEventListener('storage',event=>{if(event.key===storageKey()||event.key===null)fresh();});
setInterval(checkDay,60000);
function setTheme(dark){document.body.classList.toggle('dark',dark);$('theme').setAttribute('aria-label',dark?'ಬೆಳಕಿನ ವಿನ್ಯಾಸಕ್ಕೆ ಬದಲಿಸಿ':'ಕತ್ತಲೆ ವಿನ್ಯಾಸಕ್ಕೆ ಬದಲಿಸಿ');}
$('theme').onclick=()=>{const dark=!document.body.classList.contains('dark');setTheme(dark);write('rahasya-theme',dark?'dark':'light');};setTheme(read('rahasya-theme')!=='light');mode=read('rahasya-mode')==='hard'?'hard':'easy';load();
if(document.modelContext?.registerTool){const registry=document.modelContext;const register=tool=>{try{Promise.resolve(registry.registerTool(tool)).catch(()=>{});}catch{}};register({name:'read_current_case',description:'Read the current Kannada case and already revealed clues. Does not reveal the solution.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({date:key,mode,title:c.title,suspects:c.suspects,rooms:c.rooms,weapons:c.weapons,times:c.times,clues:c.clues.slice(0,state.highest+1),solved:state.solved})});register({name:'reveal_next_clue',description:'Reveal the next clue in the visible game. A newly revealed clue costs six points before solving.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{changeClue(1);return{clue:c.clues[state.clue],score:currentScore()};}});register({name:'submit_accusation',description:'Submit a culprit, weapon and time to check the case. An incorrect complete answer costs 15 points.',inputSchema:{type:'object',properties:{killer:{type:'string'},weapon:{type:'string'},time:{type:'string'}},required:['killer','weapon','time'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['killer','weapon','time'].includes(k))||['killer','weapon','time'].some(k=>typeof input[k]!=='string'))throw Error('ಮೂರು ಮಾನ್ಯ ಉತ್ತರಗಳು ಅಗತ್ಯ.');E.checkAnswer(c,input);for(const id of ['killer','weapon','time'])$(id).value=input[id];return accuse(input);}});}
